'AC-extraction.2504.1'; from __future__ import annotations; from decimal import Decimal; from pathlib import Path; from uuid import uuid4; import pytest; from src.extraction.base.result import StatementExtractionResult; from src.extraction.base.types import DocumentSource; from src.extraction.extension.service import ExtractionService; DECLARED_HEADER = 'Statement Currency,Statement Period Start,Statement Period End,Statement Opening Balance,Statement Closing Balance,Date,Description,Amount'; JOURNEY_HEADER = 'Statement Currency,Statement Opening Balance,Statement Closing Balance,Date,Description,Amount'; RECONCILED = f'{DECLARED_HEADER}\nSGD,2025-01-01,2025-01-31,100.00,125.00,2025-01-15,Interest,25.00\n'; UNRECONCILED = f'{DECLARED_HEADER}\nSGD,2025-01-01,2025-01-31,100.00,999.00,2025-01-15,Interest,25.00\n'; JOURNEY_UPLOAD = f'{JOURNEY_HEADER}\nSGD,20000.00,99999.00,2026-02-10,Unverified Expense,-500.00\n'; NO_BALANCES = 'Date,Description,Amount\n2025-01-15,Interest,25.00\n'
async def _parse(text: str) -> StatementExtractionResult: return await ExtractionService().parse_document(DocumentSource.resolve(path=Path('/tmp/declared.csv'), content=text.encode(), filename='declared.csv'), 'Example Bank', user_id=uuid4(), file_type='csv', account_id=uuid4(), db=None)
@pytest.mark.parametrize('text', [UNRECONCILED, JOURNEY_UPLOAD], ids=['opening-100-closing-999', 'journey-upload'])
async def test_AC_extraction_2504_1_an_unreconciled_declared_csv_stays_reviewable(text: str) -> None: result = await _parse(text); assert len(result.transactions) == 1; assert result.balance_validated is False; assert result.confidence < Decimal('0.5'); assert not any(('llm_led' in reason for reason in result.review_reasons)); assert not any(('Retry parsing' in reason for reason in result.review_reasons))
async def test_AC_extraction_2504_1_an_unreconciled_declared_csv_names_the_failed_balance_check() -> None: result = await _parse(UNRECONCILED); assert result.review_reasons == ('Balance mismatch: expected 125.00, got 999.00',); _m1_result = await _parse(RECONCILED); assert len(_m1_result.transactions) == 1; assert _m1_result.balance_validated is True; assert _m1_result.confidence == Decimal('0.8'); _m2_result = await _parse(NO_BALANCES); assert len(_m2_result.transactions) == 1; assert _m2_result.balance_validated is None; assert _m2_result.confidence == Decimal('0.25')
async def test_AC_extraction_2822_1_csv_with_currency_and_balance_columns_reaches_authoritative_confidence() -> None: 'AC-extraction.2822.1'; from src.extraction.base.reviewed_statement_envelope import supports_reviewed_statement_envelope; csv_with_currency_and_balance = 'Date,Description,Amount,Currency,Reference,Balance,Statement Opening Balance,Statement Closing Balance,Statement Period Start,Statement Period End\n2026-10-05,ACME Corp Salary,8500.00,SGD,SAL-2026-10,18500.00,10000.00,14180.00,2026-10-01,2026-10-31\n2026-10-10,Marina Bay Condo Rent,-3200.00,SGD,RENT-2026-10,15300.00,10000.00,14180.00,2026-10-01,2026-10-31\n2026-10-15,NTUC FairPrice Groceries,-320.00,SGD,POS-2026-1015,14980.00,10000.00,14180.00,2026-10-01,2026-10-31\n2026-10-20,Credit Card Bill Payment,-800.00,SGD,CC-2026-1020,14180.00,10000.00,14180.00,2026-10-01,2026-10-31\n'; result = await _parse(csv_with_currency_and_balance); assert len(result.transactions) == 4; assert result.balance_validated is True; assert all((txn.currency == 'SGD' for txn in result.transactions)); assert [txn.balance_after for txn in result.transactions] == [Decimal('18500.00'), Decimal('15300.00'), Decimal('14980.00'), Decimal('14180.00')]; assert result.confidence >= Decimal('0.85'); assert result.missing_required_facts == (); assert supports_reviewed_statement_envelope(result) is False
